 const Icon=icons[activity.icon]||Sparkles;const first=itemId||activity.rewards[0]?.itemId;const src=first&&localIcons.has(first)?`/icons/${first}.jpg`:icon;
 const [failed,setFailed]=useState(false);useEffect(()=>setFailed(false),[src]);
